-- Radora Finance & Accounts: transactional accounting foundation.
-- AI/analytics consume these records but never write to posted accounting data.
CREATE TYPE "FinanceAccountType" AS ENUM ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE');
CREATE TYPE "FinanceEntryStatus" AS ENUM ('DRAFT', 'POSTED', 'VOID');
CREATE TYPE "FinanceInvoiceStatus" AS ENUM ('DRAFT', 'ISSUED', 'PARTIALLY_PAID', 'PAID', 'OVERDUE', 'CANCELLED');
CREATE TYPE "FinancePaymentMethod" AS ENUM ('CASH', 'BANK_TRANSFER', 'CARD', 'UPI', 'CHEQUE', 'OTHER');
CREATE TYPE "FinancePaymentStatus" AS ENUM ('PENDING', 'COMPLETED', 'REFUNDED');
CREATE TYPE "FinanceExpenseStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'PAID');
CREATE TYPE "FinanceApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "FinanceBudgetStatus" AS ENUM ('DRAFT', 'ACTIVE', 'CLOSED');
CREATE TYPE "FinanceAssetStatus" AS ENUM ('ACTIVE', 'DISPOSED');

CREATE TABLE "FinanceFeeCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "description" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceFeeCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FeeStructure" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "academicYear" TEXT NOT NULL, "className" TEXT, "amount" DECIMAL(14,2) NOT NULL, "frequency" TEXT NOT NULL DEFAULT 'ANNUAL', "categoryId" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FeeStructure_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceStudentFeeAssignment" ("id" TEXT NOT NULL, "studentId" TEXT NOT NULL, "feeStructureId" TEXT NOT NULL, "assignedAmount" DECIMAL(14,2) NOT NULL, "discountAmount" DECIMAL(14,2) NOT NULL DEFAULT 0, "scholarshipAmount" DECIMAL(14,2) NOT NULL DEFAULT 0, "assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceStudentFeeAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FeeInvoice" ("id" TEXT NOT NULL, "invoiceNumber" TEXT NOT NULL, "assignmentId" TEXT, "studentId" TEXT, "issueDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dueDate" TIMESTAMP(3) NOT NULL, "subtotal" DECIMAL(14,2) NOT NULL, "discount" DECIMAL(14,2) NOT NULL DEFAULT 0, "lateFee" DECIMAL(14,2) NOT NULL DEFAULT 0, "total" DECIMAL(14,2) NOT NULL, "paidAmount" DECIMAL(14,2) NOT NULL DEFAULT 0, "status" "FinanceInvoiceStatus" NOT NULL DEFAULT 'DRAFT', "notes" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FeeInvoice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceInstallment" ("id" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "name" TEXT NOT NULL, "dueDate" TIMESTAMP(3) NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "paidAmount" DECIMAL(14,2) NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceInstallment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceDiscount" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "percentage" DECIMAL(5,2), "fixedAmount" DECIMAL(14,2), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceDiscount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceScholarship" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "sponsor" TEXT, "amount" DECIMAL(14,2) NOT NULL, "academicYear" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceScholarship_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinancePayment" ("id" TEXT NOT NULL, "reference" TEXT NOT NULL, "invoiceId" TEXT, "amount" DECIMAL(14,2) NOT NULL, "method" "FinancePaymentMethod" NOT NULL, "status" "FinancePaymentStatus" NOT NULL DEFAULT 'COMPLETED', "paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "notes" TEXT, "receivedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinancePayment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceRefund" ("id" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "reason" TEXT NOT NULL, "refundedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceRefund_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceReceipt" ("id" TEXT NOT NULL, "receiptNumber" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "paymentId" TEXT, "issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceReceipt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceAccount" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "FinanceAccountType" NOT NULL, "parentId" TEXT, "isSystem" BOOLEAN NOT NULL DEFAULT false, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceJournalEntry" ("id" TEXT NOT NULL, "entryNumber" TEXT NOT NULL, "entryDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "description" TEXT NOT NULL, "source" TEXT, "status" "FinanceEntryStatus" NOT NULL DEFAULT 'DRAFT', "totalDebit" DECIMAL(14,2) NOT NULL DEFAULT 0, "totalCredit" DECIMAL(14,2) NOT NULL DEFAULT 0, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceJournalEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceJournalLine" ("id" TEXT NOT NULL, "entryId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "debit" DECIMAL(14,2) NOT NULL DEFAULT 0, "credit" DECIMAL(14,2) NOT NULL DEFAULT 0, "memo" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceJournalLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceExpenseCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceExpenseCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceVendor" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT, "phone" TEXT, "taxId" TEXT, "address" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceVendor_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceExpenseBill" ("id" TEXT NOT NULL, "billNumber" TEXT NOT NULL, "vendorId" TEXT, "categoryId" TEXT, "billDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dueDate" TIMESTAMP(3), "amount" DECIMAL(14,2) NOT NULL, "status" "FinanceExpenseStatus" NOT NULL DEFAULT 'DRAFT', "description" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceExpenseBill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceExpenseApproval" ("id" TEXT NOT NULL, "billId" TEXT NOT NULL, "approverId" TEXT NOT NULL, "status" "FinanceApprovalStatus" NOT NULL DEFAULT 'PENDING', "comment" TEXT, "decidedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceExpenseApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceRecurringExpense" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "vendorId" TEXT, "amount" DECIMAL(14,2) NOT NULL, "frequency" TEXT NOT NULL, "nextRunAt" TIMESTAMP(3) NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceRecurringExpense_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceIncome" ("id" TEXT NOT NULL, "source" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reference" TEXT, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceIncome_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceAsset" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "assetCode" TEXT NOT NULL, "category" TEXT NOT NULL, "purchaseDate" TIMESTAMP(3), "purchaseValue" DECIMAL(14,2) NOT NULL, "currentValue" DECIMAL(14,2) NOT NULL, "status" "FinanceAssetStatus" NOT NULL DEFAULT 'ACTIVE', "location" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceAsset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceBudget" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "fiscalYear" TEXT NOT NULL, "category" TEXT NOT NULL, "allocated" DECIMAL(14,2) NOT NULL, "consumed" DECIMAL(14,2) NOT NULL DEFAULT 0, "status" "FinanceBudgetStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceBudget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceBankAccount" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "bankName" TEXT NOT NULL, "accountLast4" TEXT, "openingBalance" DECIMAL(14,2) NOT NULL DEFAULT 0, "currentBalance" DECIMAL(14,2) NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinanceBankAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinancePayrollIntegration" ("id" TEXT NOT NULL, "payrollRunId" TEXT NOT NULL, "period" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "status" TEXT NOT NULL DEFAULT 'SYNCED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinancePayrollIntegration_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "FinanceFeeCategory_code_key" ON "FinanceFeeCategory"("code");
CREATE INDEX "FeeStructure_academicYear_className_idx" ON "FeeStructure"("academicYear", "className");
CREATE INDEX "FinanceStudentFeeAssignment_studentId_idx" ON "FinanceStudentFeeAssignment"("studentId");
CREATE UNIQUE INDEX "FinanceStudentFeeAssignment_studentId_feeStructureId_key" ON "FinanceStudentFeeAssignment"("studentId", "feeStructureId");
CREATE UNIQUE INDEX "FeeInvoice_invoiceNumber_key" ON "FeeInvoice"("invoiceNumber");
CREATE INDEX "FeeInvoice_studentId_status_idx" ON "FeeInvoice"("studentId", "status");
CREATE INDEX "FeeInvoice_dueDate_status_idx" ON "FeeInvoice"("dueDate", "status");
CREATE INDEX "FinanceInstallment_dueDate_idx" ON "FinanceInstallment"("dueDate");
CREATE UNIQUE INDEX "FinanceDiscount_code_key" ON "FinanceDiscount"("code");
CREATE UNIQUE INDEX "FinanceScholarship_code_key" ON "FinanceScholarship"("code");
CREATE UNIQUE INDEX "FinancePayment_reference_key" ON "FinancePayment"("reference");
CREATE INDEX "FinancePayment_paidAt_status_idx" ON "FinancePayment"("paidAt", "status");
CREATE UNIQUE INDEX "FinanceReceipt_receiptNumber_key" ON "FinanceReceipt"("receiptNumber");
CREATE UNIQUE INDEX "FinanceReceipt_paymentId_key" ON "FinanceReceipt"("paymentId");
CREATE UNIQUE INDEX "FinanceAccount_code_key" ON "FinanceAccount"("code");
CREATE UNIQUE INDEX "FinanceJournalEntry_entryNumber_key" ON "FinanceJournalEntry"("entryNumber");
CREATE INDEX "FinanceJournalEntry_entryDate_status_idx" ON "FinanceJournalEntry"("entryDate", "status");
CREATE INDEX "FinanceJournalLine_accountId_idx" ON "FinanceJournalLine"("accountId");
CREATE UNIQUE INDEX "FinanceExpenseCategory_code_key" ON "FinanceExpenseCategory"("code");
CREATE UNIQUE INDEX "FinanceExpenseBill_billNumber_key" ON "FinanceExpenseBill"("billNumber");
CREATE INDEX "FinanceExpenseBill_billDate_status_idx" ON "FinanceExpenseBill"("billDate", "status");
CREATE UNIQUE INDEX "FinanceAsset_assetCode_key" ON "FinanceAsset"("assetCode");
CREATE UNIQUE INDEX "FinanceBudget_fiscalYear_category_key" ON "FinanceBudget"("fiscalYear", "category");
CREATE UNIQUE INDEX "FinancePayrollIntegration_payrollRunId_key" ON "FinancePayrollIntegration"("payrollRunId");

ALTER TABLE "FeeStructure" ADD CONSTRAINT "FeeStructure_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "FinanceFeeCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceStudentFeeAssignment" ADD CONSTRAINT "FinanceStudentFeeAssignment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceStudentFeeAssignment" ADD CONSTRAINT "FinanceStudentFeeAssignment_feeStructureId_fkey" FOREIGN KEY ("feeStructureId") REFERENCES "FeeStructure"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FeeInvoice" ADD CONSTRAINT "FeeInvoice_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "FinanceStudentFeeAssignment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FeeInvoice" ADD CONSTRAINT "FeeInvoice_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FeeInvoice" ADD CONSTRAINT "FeeInvoice_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceInstallment" ADD CONSTRAINT "FinanceInstallment_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "FeeInvoice"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FinancePayment" ADD CONSTRAINT "FinancePayment_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "FeeInvoice"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FinancePayment" ADD CONSTRAINT "FinancePayment_receivedById_fkey" FOREIGN KEY ("receivedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceRefund" ADD CONSTRAINT "FinanceRefund_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "FeeInvoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceReceipt" ADD CONSTRAINT "FinanceReceipt_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "FeeInvoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceReceipt" ADD CONSTRAINT "FinanceReceipt_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "FinancePayment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FinanceAccount" ADD CONSTRAINT "FinanceAccount_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "FinanceAccount"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FinanceJournalEntry" ADD CONSTRAINT "FinanceJournalEntry_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceJournalLine" ADD CONSTRAINT "FinanceJournalLine_entryId_fkey" FOREIGN KEY ("entryId") REFERENCES "FinanceJournalEntry"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FinanceJournalLine" ADD CONSTRAINT "FinanceJournalLine_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "FinanceAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceExpenseBill" ADD CONSTRAINT "FinanceExpenseBill_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "FinanceVendor"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FinanceExpenseBill" ADD CONSTRAINT "FinanceExpenseBill_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "FinanceExpenseCategory"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FinanceExpenseBill" ADD CONSTRAINT "FinanceExpenseBill_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceExpenseApproval" ADD CONSTRAINT "FinanceExpenseApproval_billId_fkey" FOREIGN KEY ("billId") REFERENCES "FinanceExpenseBill"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FinanceExpenseApproval" ADD CONSTRAINT "FinanceExpenseApproval_approverId_fkey" FOREIGN KEY ("approverId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceRecurringExpense" ADD CONSTRAINT "FinanceRecurringExpense_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "FinanceVendor"("id") ON DELETE SET NULL ON UPDATE CASCADE;
